<script lang="ts">
  import { onMount } from 'svelte';
  import Button from '$lib/components/ui/button/button.svelte';
  import { tr } from '../preferences.svelte';
  import { post,message,uuid,type Request } from './types';
  let {request,active=true,onDirtyChange,scope='all'}:{request:Request;active?:boolean;onDirtyChange?:(dirty:boolean)=>void;scope?:'all'|'bionic'|'comfyui'}=$props();
  let services=$state<any[]>([]),setup=$state<any>(null),profiles=$state<Record<string,Record<string,string>>>({}),candidates=$state<Record<string,any[]>>({});
  let nonce=$state(''),storageKey='',refreshing=false;
  let pending=$state<Record<string,string>>({}),intention=$state<any>(null),consents=$state<Record<string,boolean>>({}),busy=$state(''),failure=$state(''),notice=$state('');
  const names:Record<string,string>={bionic:'Bionic',comfyui:'ComfyUI'};
  const visibleServices=$derived(services.filter(service=>scope==='all'||service.id===scope));
  const fields:Record<string,string[]>={bionic:['appPath','cliPath','apiInfoPath'],comfyui:['workingDirectory','pythonPath','entryPath']};
  const fieldName=(key:string)=>({appPath:tr('Application Bionic','Bionic application'),cliPath:tr('Commande Bionic','Bionic command'),apiInfoPath:tr('Fichier d’informations API','API information file'),workingDirectory:tr('Dossier ComfyUI','ComfyUI folder'),pythonPath:tr('Exécutable Python','Python executable'),entryPath:tr('Script de démarrage','Startup script')}[key]||key);
  const dirty=$derived(!!setup&&(JSON.stringify(profiles)!==JSON.stringify(Object.fromEntries((setup.services||[]).map((item:any)=>[item.id,{...item.profile}])))||Object.values(consents).some(Boolean)));
  $effect(()=>{onDirtyChange?.(dirty);});
  const headers=()=>({'X-Local-Service-CSRF':nonce});
  const ownershipName=(value:string)=>({ 'desktop-and-api':tr('Application et API gérées par Canaé','Application and API managed by Canaé'),'api-only':tr('API gérée · application externe','Managed API · external application'),external:tr('Application et API externes','External application and API') } as Record<string,string>)[value]||tr('Propriété inconnue','Ownership unknown');
  const desktopName=(value:string)=>({running:tr('En cours','Running'),stopped:tr('Arrêtée','Stopped'),external:tr('Externe · non contrôlée','External · not controlled')} as Record<string,string>)[value]||tr('Inconnu','Unknown');
  const recoveryStop=(service:any,action:string)=>action==='stop'&&service.id==='bionic'&&service.process?.recoveryStop===true;
  const availableAction=(service:any,action:string)=>service.actions?.[action]?.allowed===true&&(!pending[service.id]||recoveryStop(service,action));
  function confirmation(target:any){
    if(target.id!=='bionic'||target.action!=='stop')return tr('Cette action peut interrompre l’accès au service. Les états et la révision seront revérifiés avant tout effet.','This action may interrupt access to the service. Status and revision will be checked again before any effect.');
    if(target.ownership==='desktop-and-api')return target.recoveryStop?tr('Cette nouvelle demande explicite revérifie l’API et les droits, demande son arrêt si nécessaire, puis ferme uniquement l’application Bionic démarrée par Canaé après vérification de son identité. Aucun arrêt précédent n’est rejoué.','This new explicit request checks the API again and verifies permissions, requests its stop if needed, then closes only the Bionic application started by Canaé after checking its identity. No previous stop request is replayed.'):tr('Cette action arrête l’API et ferme l’application Bionic démarrée par Canaé. Les identités et les droits seront revérifiés avant tout effet.','This action stops the API and closes the Bionic application started by Canaé. Identity and permissions will be checked again before any effect.');
    if(target.ownership==='api-only')return tr('Cette action arrête uniquement l’API gérée par Canaé. L’application Bionic externe n’est pas fermée par cette action.','This action stops only the API managed by Canaé. It does not close the external Bionic application.');
    return tr('La propriété de l’application n’est pas confirmée. Aucun arrêt de son application ne peut être annoncé ici. Les droits du serveur restent déterminants.','Application ownership is unconfirmed. Stopping its application cannot be claimed here. Server permissions remain authoritative.');
  }
  function persist(){if(storageKey)sessionStorage.setItem(storageKey,JSON.stringify(pending));}
  async function recover(){for(const [id,key] of Object.entries(pending)){try{const result=await request('/api/local-service-operations/'+encodeURIComponent(key));const operation=result.operation||result;if(operation?.id){services=services.map(item=>item.id===id?{...item,operation}:item);const next={...pending};delete next[id];pending=next;persist();}}catch{/* Unknown acceptance remains visible; never resubmit. */}}}
  async function refresh(){if(refreshing)return;refreshing=true;try{const data=await request('/api/local-services');nonce=data.csrfNonce||'';services=data.services||[];await recover();if(!setup){setup=await request('/api/local-service-setup',{headers:headers()});profiles=Object.fromEntries((setup.services||[]).map((item:any)=>[item.id,{...item.profile}]));}}catch(error){failure=message(error);}finally{refreshing=false;}}
  async function configure(id:string,action:string){busy=id;failure='';notice='';try{const body:any={serviceId:id};if(action==='save')Object.assign(body,{expectedRevision:setup.revision,exclusiveControl:true,profile:Object.fromEntries(Object.entries(profiles[id]||{}).filter(([,value])=>value?.trim()).map(([key,value])=>[key,value.trim()]))});const result=await post(request,'/api/local-service-setup/'+action,body,headers());if(action==='save'){setup=result;consents={...consents,[id]:false};notice=tr('Profil enregistré.','Profile saved.');await refresh();}else{candidates={...candidates,[id]:result.candidates||[]};if(result.candidates?.[0])profiles={...profiles,[id]:{...result.candidates[0].profile}};notice=result.cancelled?tr('Sélection annulée.','Selection cancelled.'):result.candidates?.length?tr('Vérifie le profil proposé avant de l’enregistrer.','Review the suggested profile before saving it.'):tr('Aucune installation détectée.','No installation detected.');}}catch(error){failure=message(error);if(action==='save'){try{setup=await request('/api/local-service-setup',{headers:headers()});}catch{}}}finally{busy='';}}
  function intend(service:any,action:string){if(busy||!availableAction(service,action))return;intention={id:service.id,action,revision:service.revision,ownership:service.process?.ownership,recoveryStop:recoveryStop(service,action)};}
  async function act(){if(!intention||busy)return;const current=services.find(item=>item.id===intention.id);if(!current||current.revision!==intention.revision||!availableAction(current,intention.action)||current.id==='bionic'&&current.process?.ownership!==intention.ownership){failure=tr('L’état du service a changé. Relis-le avant de confirmer à nouveau.','Service status changed. Refresh it before confirming again.');return;}const target={...intention},key=uuid();busy=target.id;failure='';notice='';try{pending={...pending,[target.id]:key};persist();intention=null;const value=await post(request,'/api/local-services/'+target.id+'/actions',{action:target.action,expectedRevision:target.revision,idempotencyKey:key},headers());services=services.map(item=>item.id===target.id?{...item,operation:value.operation||value}:item);const next={...pending};delete next[target.id];pending=next;persist();notice=tr('Opération acceptée. Le suivi continue sur le serveur.','Operation accepted. Tracking continues on the server.');}catch(error:any){failure=message(error);if(error.status>=400&&error.status<500&&error.status!==408){const next={...pending};delete next[target.id];pending=next;persist();}else notice=tr('Résultat non confirmé. Vérification par lecture uniquement.','Result unconfirmed. Checking through read requests only.');await refresh();}finally{busy='';}}
  async function reload(){busy='reload';failure='';try{await post(request,'/api/local-services/configuration/reload',{},headers());setup=null;await refresh();notice=tr('Configuration relue.','Configuration refreshed.');}catch(error){failure=message(error);await refresh();}finally{busy='';}}
  function forget(id:string){const next={...pending};delete next[id];pending=next;persist();notice=tr('Suivi local fermé. Aucun processus n’a été arrêté ou relancé.','Local tracking closed. No process was stopped or restarted.');}
  onMount(()=>{void(async()=>{try{const ping=await request('/api/ping');storageKey='bionic:llama-services:'+ping.instanceId;pending=JSON.parse(sessionStorage.getItem(storageKey)||'{}');}catch{}await refresh();})();const timer=setInterval(()=>{if(active&&!document.hidden)void refresh();},3000);return()=>clearInterval(timer);});
</script>

<h3>{scope==='all'?tr('Lancement des serveurs','Server startup'):scope==='bionic'?tr('Lancement de Bionic','Bionic startup'):tr('Lancement de ComfyUI','ComfyUI startup')}</h3><p class="settings-description">{tr('Démarrage et arrêt manuels des services configurés. Chaque action dépend de l’identité du processus, de l’activité et des droits confirmés par le serveur.','Manually start and stop configured services. Each action depends on process identity, activity and permissions confirmed by the server.')}</p>
<div class="settings-actions"><Button variant="outline" onclick={refresh} disabled={!!busy}>{tr('Actualiser les états','Refresh status')}</Button><Button variant="ghost" onclick={reload} disabled={!!busy||!nonce}>{tr('Relire la configuration du PC','Reload PC configuration')}</Button></div>
{#if !visibleServices.length}<p>{tr('Aucun service disponible.','No service available.')}</p>{/if}
{#each visibleServices as service (service.id)}
  <section class="service-section" aria-label={names[service.id]||service.id}><h3>{names[service.id]||service.id}</h3>
  <dl class="settings-dl"><dt>{tr('Processus','Process')}</dt><dd>{service.process?.state||tr('Inconnu','Unknown')}</dd><dt>API</dt><dd>{service.api?.state||tr('Non vérifiée','Not checked')}</dd><dt>{tr('Activité','Activity')}</dt><dd>{service.activity?.state||tr('Inconnue','Unknown')}{service.activity?.count?' · '+service.activity.count:''}</dd><dt>{tr('Modèles','Models')}</dt><dd>{service.model?.state||tr('Non vérifiés','Not checked')}</dd></dl>
  {#if service.id==='bionic'}<dl class="settings-dl"><dt>{tr('Contrôle de Bionic','Bionic control')}</dt><dd data-service-ownership={service.process?.ownership||'unknown'}>{ownershipName(service.process?.ownership)}</dd><dt>{tr('Application Bionic','Bionic application')}</dt><dd data-desktop-state={service.process?.desktopState||'unknown'}>{desktopName(service.process?.desktopState)}</dd></dl>{#if service.process?.recoveryStop}<p class="settings-feedback">{tr('Un nouvel arrêt explicite réévalue l’API et ne peut fermer que l’application démarrée par Canaé si le serveur confirme son identité et les droits ; aucune relecture ne ferme l’application.','A new explicit stop rechecks the API and can close only the application started by Canaé if the server confirms its identity and permissions; reading status never closes the application.')}</p>{/if}{/if}
  <div class="settings-actions">{#each ['start','stop','restart'] as action}<Button variant={action==='start'?'default':'outline'} disabled={!!busy||!availableAction(service,action)} onclick={()=>intend(service,action)}>{action==='start'?tr('Démarrer','Start'):action==='stop'?tr('Arrêter','Stop'):tr('Redémarrer','Restart')} {names[service.id]}</Button>{/each}</div>
  {#if pending[service.id]}<div class="settings-feedback"><p>{tr('Acceptation non confirmée. Aucun nouvel envoi automatique. Vérifie le service sur le PC si cet état persiste.','Acceptance unconfirmed. No automatic resubmission. Check the service on the PC if this persists.')}</p><Button variant="outline" onclick={refresh}>{tr('Vérifier le suivi','Check tracking')}</Button><Button variant="ghost" onclick={()=>forget(service.id)}>{tr('Fermer le suivi local','Close local tracking')}</Button></div>{/if}
  {#if service.operation}<p class="settings-feedback" role="status">{tr('Dernière opération','Latest operation')} : {service.operation.status} · {service.operation.phase||''}{service.operation.resultCode?' · '+service.operation.resultCode:''}</p>{/if}
  <details><summary>{tr('Profil de lancement et détails','Launch profile and details')}</summary>
    <p class="settings-description">{service.configuration?.profileLabel||service.configuration?.status} · {service.controlMode}</p>
    {#if setup?.canConfigure}<div class="settings-actions"><Button variant="outline" onclick={()=>configure(service.id,'discover')} disabled={!!busy}>{tr('Détecter une installation','Detect installation')}</Button><Button variant="outline" onclick={()=>configure(service.id,'pick')} disabled={!!busy}>{tr('Choisir sur le PC','Choose on PC')}</Button></div>
    {#if candidates[service.id]?.length}<label class="setting-field">{tr('Installations détectées','Detected installations')}<select onchange={event=>profiles={...profiles,[service.id]:{...candidates[service.id][Number(event.currentTarget.value)].profile}}}>{#each candidates[service.id] as candidate,index}<option value={index}>{candidate.label}</option>{/each}</select></label>{/if}
    {#each fields[service.id]||[] as field}<label class="setting-field">{fieldName(field)}<input value={profiles[service.id]?.[field]||''} oninput={event=>profiles={...profiles,[service.id]:{...profiles[service.id],[field]:event.currentTarget.value}}} disabled={!!busy} autocomplete="off" spellcheck="false" /></label>{/each}
    <label class="setting-check"><input type="checkbox" checked={consents[service.id]||false} onchange={event=>consents={...consents,[service.id]:event.currentTarget.checked}} />{tr('Confier au compagnon le contrôle exclusif de ce lancement.','Give the companion exclusive control of this launch.')}</label><Button onclick={()=>configure(service.id,'save')} disabled={!!busy||!consents[service.id]}>{tr('Enregistrer le profil','Save launch profile')}</Button>
    {:else}<p class="settings-description">{tr('La préparation du lancement s’effectue depuis ce PC, via son adresse locale.','Configure the launch from this PC using its local address.')}</p>{/if}
    <pre>{JSON.stringify({configuration:service.configuration,actions:service.actions},null,2)}</pre>
  </details></section>
{/each}
{#if intention&&(scope==='all'||intention.id===scope)}<div class="confirm-action" role="group" aria-label={tr('Confirmer l’action du serveur','Confirm server action')}><h3>{tr('Confirmer l’action','Confirm action')} · {names[intention.id]}</h3><p class="settings-description">{confirmation(intention)}</p><div class="settings-actions"><Button onclick={act} disabled={!!busy||services.find(item=>item.id===intention.id)?.revision!==intention.revision||!availableAction(services.find(item=>item.id===intention.id)||{},intention.action)}>{tr('Confirmer','Confirm')}</Button><Button variant="ghost" onclick={()=>intention=null}>{tr('Annuler','Cancel')}</Button></div></div>{/if}
{#if failure}<p class="settings-error" role="alert">{failure}</p>{/if}{#if notice}<p class="settings-feedback" role="status">{notice}</p>{/if}
